int solve_quadratic(double a, double b, double c, double *r1, double *r2) {
    double d = b * b - 4 * a * c;
    if (d < 0) return 0;
    double s = sqrt(d);
    *r1 = (-b + s) / (2 * a);
    *r2 = (-b - s) / (2 * a);
    return (d == 0) ? 1 : 2;
}

int main(void) {
    double r1, r2;
    int count = solve_quadratic(2, -4, 1, &r1, &r2);
    printf("Roots: %.3f, %.3f (count=%d)\n", r1, r2, count);
    return 0;
}

