    double x = (A[0][2] - A[0][1] * y) / A[0][0];
    printf("Solution: x = %.1f, y = %.1f\n", x, y);
}
int main(void) {
    double A[2][3] = {{2, 1, 5}, {1, -1, 1}};
    solve2x2(A);
    return 0;
}

